INSERT OR IGNORE INTO Certification VALUES('cert-shop-orientation','shop-orientation','Shop Orientation','Required safety and space orientation for all members before using any equipment.',1,'[]',NULL,1,1,1748797200000,1788807600000,NULL);
INSERT OR IGNORE INTO Certification VALUES('cert-hand-tools-drill-press','hand-tools-drill-press','Hand Tools and Drill Press','Drill press and handheld power tool safety for shared shop use.',0,'["cert-shop-orientation"]',24,2,1,1788807600000,1788807600000,NULL);
INSERT OR IGNORE INTO Certification VALUES('cert-3d-printing','3d-printing','3D Printing (FDM)','Prusa FDM setup, PrusaSlicer, first-layer checks, and filament basics. Resin is a separate cert.',0,'["cert-shop-orientation"]',24,3,1,1748797200000,1788807600000,NULL);
INSERT OR IGNORE INTO Certification VALUES('cert-resin-printing','resin-printing','Resin Printing','Elegoo Saturn resin safety, PPE, wash/cure, and Chitubox workflow. Separate from FDM.',0,'["cert-shop-orientation"]',12,4,1,1788807600000,1788807600000,NULL);
INSERT OR IGNORE INTO Certification VALUES('cert-laser-cutter','laser-cutter','Laser Cutter','Epilog Fusion Pro operation, never-cut materials, fire safety, and CorelDRAW/Inkscape workflow.',0,'["cert-shop-orientation"]',12,5,1,1748797200000,1788807600000,NULL);
INSERT OR IGNORE INTO Certification VALUES('cert-woodshop-basics','woodshop-basics','Woodshop Basics','Band saw, miter saw, jointer, planer, and router table safety.',0,'["cert-shop-orientation"]',24,6,1,1748797200000,1788807600000,NULL);
INSERT OR IGNORE INTO Certification VALUES('cert-table-saw','table-saw','Table Saw','Table saw setup, rip/crosscut technique, push sticks, and kickback prevention.',0,'["cert-shop-orientation","cert-woodshop-basics"]',12,7,1,1748797200000,1788807600000,NULL);
INSERT OR IGNORE INTO Certification VALUES('cert-cnc-plasma','cnc-plasma','CNC Plasma','Avid Pro6060 plasma hazards, Mach4 operation, and VCarve toolpaths. Solo OK; unattended never.',0,'["cert-shop-orientation"]',12,8,1,1788807600000,1788807600000,NULL);
INSERT OR IGNORE INTO Certification VALUES('cert-sewing-machines','sewing-machines','Sewing Machines','Threading, tension, stitch selection, and safe use of shop sewing machines.',0,'["cert-shop-orientation"]',24,9,1,1748797200000,1788807600000,NULL);
INSERT OR IGNORE INTO Certification VALUES('cert-vinyl-cutter','vinyl-cutter','Vinyl Cutter','Silhouette Cameo cutting, weeding, transfer tape, and cutter care.',0,'["cert-shop-orientation"]',24,10,1,1748797200000,1788807600000,NULL);
INSERT OR IGNORE INTO Certification VALUES('cert-embroidery-machine','embroidery-machine','Embroidery Machine','Hooping, digitizing basics, thread paths, and embroidery machine care.',0,'["cert-shop-orientation"]',24,11,1,1748797200000,1788807600000,NULL);
INSERT OR IGNORE INTO Certification VALUES('cert-sublimation','sublimation','Sublimation','Sublimation printer, heat press temperatures, and substrate prep.',0,'["cert-shop-orientation"]',24,12,1,1748797200000,1788807600000,NULL);
