INSERT OR IGNORE INTO LearningModule VALUES('mod-shop-orientation','shop-orientation','Shop Orientation','Required before any machine access. Conduct, PPE, dust, and emergency response.','cert-shop-orientation',1,0,'confirmed',80,3,1,1788721200000,1788721200000,NULL);
INSERT OR IGNORE INTO LearningModule VALUES('mod-hand-tools-drill-press','hand-tools-drill-press','Hand Tools and Drill Press','The website lists ''hand held power tools, drill press'' - this cert covers what most members will actually touch first. Not in the portal spec; add it.','cert-hand-tools-drill-press',0,0,'confirmed',80,3,2,1788721200000,1788721200000,NULL);
INSERT OR IGNORE INTO LearningModule VALUES('mod-laser-cutter','laser-cutter','Laser Cutter (Epilog Fusion Pro 32)','Epilog Fusion Pro 32, 80W CO2, rim drive rotary, driven from CorelDRAW. Fire and fumes are the two hazards that will hurt someone or shut the shop down.','cert-laser-cutter',0,0,'confirmed',80,3,3,1788721200000,1788721200000,NULL);
INSERT OR IGNORE INTO LearningModule VALUES('mod-3d-printing','3d-printing','3D Printing - FDM (Prusa i3 MK3S)','Prusa i3 MK3S with PrusaSlicer. Resin has been split into its own certification - see mod-resin-printing.','cert-3d-printing',0,0,'confirmed',80,3,4,1788721200000,1788721200000,NULL);
INSERT OR IGNORE INTO LearningModule VALUES('mod-resin-printing','resin-printing','Resin Printing (Elegoo Saturn 2 + wash/cure)','Elegoo Saturn 2 (8K) with a wash and cure station. Lowest injury risk on the day, highest chronic risk in the building. Prints run unattended - the exception to the shop''s attended-operation rule.','cert-resin-printing',0,0,'confirmed',80,3,5,1788721200000,1788721200000,NULL);
INSERT OR IGNORE INTO LearningModule VALUES('mod-vinyl-cutter','vinyl-cutter','Vinyl Cutter (Silhouette Cameo 4)','Silhouette Cameo 4. Low hazard, high throughput - a good candidate for a quiz-only cert with a very short checkoff.','cert-vinyl-cutter',0,0,'confirmed',80,3,6,1788721200000,1788721200000,NULL);
INSERT OR IGNORE INTO LearningModule VALUES('mod-sewing','sewing-machine','Sewing Machine (Singer)','Singer machine. Feeds directly into the bowl cozy and stocking classes.','cert-sewing-machines',0,0,'confirmed',80,3,7,1788721200000,1788721200000,NULL);
INSERT OR IGNORE INTO LearningModule VALUES('mod-cnc-plasma','cnc-plasma','CNC Plasma Table (Avid Pro6060)','Avid CNC Pro6060, 5''x5'', Mach4 control, VCarve CAD/CAM. UV, metal fume, molten spatter, high voltage and an unattended moving gantry.','cert-cnc-plasma',0,0,'confirmed',80,3,8,1788721200000,1788721200000,NULL);
INSERT OR IGNORE INTO LearningModule VALUES('mod-table-saw','table-saw','Table Saw','Table Saw knowledge path for The Box.','cert-table-saw',0,0,'confirmed',80,3,9,1788721200000,1788721200000,NULL);
INSERT OR IGNORE INTO LearningModule VALUES('mod-woodshop-basics','woodshop-basics','Woodshop Basics','Woodshop Basics knowledge path for The Box.','cert-woodshop-basics',0,0,'confirmed',80,3,10,1788721200000,1788721200000,NULL);
INSERT OR IGNORE INTO LearningModule VALUES('mod-embroidery-machine','embroidery-machine','Embroidery Machine','Brother-class single-needle embroidery: threading, USB designs, hooping, and stabilizer selection. Confirm exact model at the machine.','cert-embroidery-machine',0,0,'confirmed',80,3,11,1788721200000,1788721200000,NULL);
INSERT OR IGNORE INTO LearningModule VALUES('mod-sublimation','sublimation','Sublimation (printer + heat press)','Sawgrass-class dye-sub printer and heat press. Mirror, polyester blanks, press temperatures, and platen safety.','cert-sublimation',0,0,'confirmed',80,3,12,1788721200000,1788721200000,NULL);
