INSERT OR IGNORE INTO ContentPage VALUES('content-waiver',NULL,NULL,'waiver','Liability Waiver & Assumption of Risk',replace('<p>By signing this waiver, you acknowledge that use of The Box makerspace involves inherent risks including injury from tools, equipment, materials, and other members.</p>\n<p>You agree to follow all posted safety rules, complete required orientations and certifications before using equipment, and accept full responsibility for your projects and personal belongings.</p>\n<p>You release Discover Burien and The Box staff, volunteers, and affiliates from liability to the fullest extent permitted by law, except for gross negligence or willful misconduct.</p>\n<p>This waiver (version 2026.1) remains in effect until superseded by a newer published version that you must re-sign.</p>','\n',char(10)),'content/waiver.md','waiver','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-hours',NULL,NULL,'hours','Hours of Operation','<ul><li>Sunday 11:00 AM – 5:00 PM</li><li>Monday 4:00 – 8:00 PM</li><li>Tuesday 4:00 – 8:00 PM</li><li>Wednesday 3:00 – 8:00 PM</li><li>Thursday 11:00 AM – 8:00 PM</li><li>Friday 11:00 AM – 8:00 PM</li><li>Saturday 11:00 AM – 6:00 PM</li></ul><p>Holiday closures and special events are posted at the shop and on the Discover Burien calendar.</p>','content/hours/hours.md','hours','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-member-expectations',NULL,NULL,'member-expectations','Member Expectations',replace('<p>Members treat people, tools, and the space with respect. Clean your station, return tools, and leave the shop better than you found it.</p>\n<p>Never use equipment you are not certified for. Ask staff when unsure. Report damaged tools immediately.</p>\n<p>Harassment, discrimination, and unsafe behavior are grounds for suspension or revocation of membership.</p>','\n',char(10)),'content/policies/member-expectations.md','policy','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-storage',NULL,NULL,'storage-abandoned-property','Storage & Abandoned Property',replace('<p>Short-term project storage is available in labeled member cubbies during active projects (up to 14 days).</p>\n<p>Items left beyond the labeled date or after membership lapses may be treated as abandoned and donated or discarded after 30 days notice.</p>\n<p>The Box is not responsible for lost, stolen, or damaged personal property.</p>','\n',char(10)),'content/policies/storage-abandoned-property.md','policy','2025.4',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-guests',NULL,NULL,'guests-and-minors','Guests & Minors','<p>Adult guests may visit during open hours with a member host and must sign a day waiver at the front desk.</p><p class="todo-flag">TODO: Confirm age thresholds, guardian requirements, and which machines are off-limits to minors under 16. Legal review pending before publish.</p><p>Minors must be accompanied by a guardian who remains on-site unless enrolled in a staffed youth program.</p>','content/policies/guests-and-minors.md','policy','2025.4',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-volunteering',NULL,NULL,'volunteering','Volunteering at The Box',replace('<p>Volunteers help with open hours, orientations, tool maintenance, and community events.</p>\n<p>All volunteers complete Shop Orientation and a short onboarding with staff before unsupervised shifts.</p>\n<p>Express interest through the volunteer form; staff will follow up within about one week.</p>','\n',char(10)),'content/policies/volunteering.md','policy','2025.4',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-faq',NULL,NULL,'faq','Frequently Asked Questions',replace('<p>Do I need a membership to take a class? Many workshops are open to the public; membership discounts may apply.</p>\n<p>How do certifications work? Complete the knowledge module, then book an in-person checkoff with staff.</p>\n<p>Can I reserve machines? Yes — high-demand tools like the laser and table saw recommend reservations.</p>','\n',char(10)),'content/policies/faq.md','policy','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-vol-front-desk',NULL,NULL,'volunteer-front-desk','Front Desk Greeter',replace('<p>Welcome members, check waivers, and help newcomers find orientations and class check-in.</p>\n<p>Ideal for friendly communicators who know (or want to learn) the shop layout.</p>','\n',char(10)),'content/volunteer/front-desk.md','volunteer','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-vol-shop-steward',NULL,NULL,'volunteer-shop-steward','Shop Steward','<p>Volunteer <strong>four hours a week</strong> (one shift) and receive a <strong>free Maker membership</strong> plus free certifications.</p><p>Stewards cover open hours and can <strong>schedule maintenance blocks</strong> on any machine. Want a deeper commitment on one tool? See Tool Champion.</p>','content/volunteer/shop-steward.md','volunteer','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-vol-tool-champion',NULL,NULL,'volunteer-tool-champion','Tool Champion',replace('<h1>Tool Champion</h1>\n<p>Own one machine for <strong>two months</strong>: keep it safe and clean, help members get certified, and flag repairs early.</p>\n<p><strong>What you do</strong></p>\n<ul>\n<li>Weekly check-ins on your machine (consumables, blades, alignment, cleanliness)</li>\n<li>Help with certification checkoffs when staff ask</li>\n<li>Flag downtime early so staff or Shop Stewards can block the machine in the portal</li>\n</ul>\n<p><strong>Path to Shop lead</strong>\nAfter you <strong>complete championships on three different machines</strong>, we’ll invite you onto the <strong>Shop lead</strong> track — broader floor leadership (training curriculum, area standards, mentoring new champions). That’s our name for what some spaces call an “omni” or multi-shop lead.</p>\n<p>Staff reviews each request. Apply below and pick a machine.</p>\n','\n',char(10)),'content/volunteer/tool-champion.md','volunteer','2026.1',1788278400000,1,1748797200000,1788807600000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-vol-events',NULL,NULL,'volunteer-events','Events & Outreach Helper',replace('<p>Help set up community make-nights, tabling at Discover Burien events, and post-event cleanup.</p>\n<p>Flexible evening and weekend shifts; no machine certifications required.</p>','\n',char(10)),'content/volunteer/events.md','volunteer','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-class-shop-orient',NULL,NULL,'class-shop-orientation','Shop Orientation Class',replace('<p>A guided walkthrough of The Box: safety culture, PPE, emergency exits, and how certifications work.</p>\n<p>Required before independent machine use. About 90 minutes including Q&A.</p>','\n',char(10)),'content/classes/shop-orientation.md','class','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-class-3d-intro',NULL,NULL,'class-3d-printing-intro','Intro to 3D Printing',replace('<p>Learn FDM basics: slicing, bed leveling concepts, filament handling, and first print workflow on our Prusa printers.</p>\n<p>Completing this workshop counts toward the knowledge portion of the 3D Printing certification.</p>','\n',char(10)),'content/classes/3d-printing-intro.md','class','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-class-laser',NULL,NULL,'class-laser-basics','Laser Cutter Basics',replace('<p>Material selection, file prep, focus, and fire-watch habits on the CO₂ laser.</p>\n<p>Prerequisite: Shop Orientation. Checkoff available after the session for eligible members.</p>','\n',char(10)),'content/classes/laser-basics.md','class','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-class-wood',NULL,NULL,'class-woodshop-safety','Woodshop Safety & Basics',replace('<p>PPE, dust collection, and safe use of miter saw, band saw, and planer/jointer stations.</p>\n<p>Table saw certification is a separate checkoff after this basics course.</p>','\n',char(10)),'content/classes/woodshop-safety.md','class','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-class-sewing',NULL,NULL,'class-sewing-basics','Sewing Machine Basics',replace('<p>Threading, bobbins, tension, and straight-stitch confidence on our Janome machines.</p>\n<p>Bring a simple project idea; fabric scraps provided.</p>','\n',char(10)),'content/classes/sewing-basics.md','class','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-class-open-studio',NULL,NULL,'class-open-studio-night','Open Studio Night',replace('<p>Staffed open hours for certified members to work on personal projects with peer support.</p>\n<p>Free for active members. Bring your own materials unless otherwise noted.</p>','\n',char(10)),'content/classes/open-studio-night.md','class','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-class-embroidery',NULL,NULL,'class-embroidery-intro','Embroidery Machine Intro',replace('<p>Hooping, design transfer, and first stitch-outs on the Brother PE800.</p>\n<p>Great follow-on after sewing basics.</p>','\n',char(10)),'content/classes/embroidery-intro.md','class','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-class-sublimation',NULL,NULL,'class-sublimation-workshop','Sublimation Workshop',replace('<p>Print, press, and peel: mugs, shirts, and hard blanks with our Sawgrass + heat press setup.</p>\n<p>Materials fee included for one blank of your choice.</p>','\n',char(10)),'content/classes/sublimation-workshop.md','class','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-lesson-so-1',NULL,NULL,'lesson-shop-orientation-welcome','Welcome to The Box',replace('<p>The Box is Discover Burien’s community makerspace. This lesson covers who we serve, how membership works, and what “leave it better” means in practice.</p>\n<p>You will learn where to find staff, first aid, fire extinguishers, and the emergency exit nearest the woodshop.</p>','\n',char(10)),'content/lessons/shop-orientation/welcome.md','lesson','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-lesson-so-2',NULL,NULL,'lesson-shop-orientation-safety','Safety Culture & PPE',replace('<p>Eye and ear protection, closed-toe shoes, and hair/jewelry rules apply in active shop areas.</p>\n<p>Never interrupt someone mid-cut. Use the buddy system for high-risk tools and stop work if something feels unsafe.</p>','\n',char(10)),'content/lessons/shop-orientation/safety.md','lesson','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-lesson-so-3',NULL,NULL,'lesson-shop-orientation-access','Badges, Certs & Reservations',replace('<p>Badge readers gate powered equipment. Your badge only unlocks machines you are certified for.</p>\n<p>Reserve high-demand tools, cancel early when plans change, and never share badges.</p>','\n',char(10)),'content/lessons/shop-orientation/access.md','lesson','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-lesson-3d-1',NULL,NULL,'lesson-3d-slicing','Slicing Basics',replace('<p>Slicers convert STL/3MF models into G-code. Learn profiles, layer height, supports, and bed adhesion settings used on our Prusa and Bambu printers.</p>\n<p>Always preview toolpaths before sending a job and confirm filament type matches the profile.</p>','\n',char(10)),'content/lessons/3d-printing/slicing.md','lesson','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-lesson-3d-2',NULL,NULL,'lesson-3d-materials','Materials & Bed Prep',replace('<p>PLA is the shop default. PETG and specialty filaments need approved profiles and sometimes an enclosure.</p>\n<p>Clean the bed, check first-layer squish, and never leave resin printers unattended during print or wash/cure.</p>','\n',char(10)),'content/lessons/3d-printing/materials.md','lesson','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-lesson-3d-3',NULL,NULL,'lesson-3d-troubleshooting','Troubleshooting & Cleanup',replace('<p>Common issues: warping, stringing, nozzle clogs, and failed first layers. Pause safely, ask staff before disassembling hotends.</p>\n<p>Remove failed prints, scrape residue carefully, and log filament usage and any faults in the shop notebook.</p>','\n',char(10)),'content/lessons/3d-printing/troubleshooting.md','lesson','2026.1',1788278400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-support',NULL,NULL,'support','Support The Box','<p>Membership keeps the lights on. Donations and sponsorships open the door wider — scholarships, tools, and programs for Burien neighbors who couldn’t otherwise join.</p>','content/support/support.md','other','2026.1',1788548400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-wishlist',NULL,NULL,'wishlist','Wishlist','<p>Pick a station or a $15 spool of filament on the <a href="/wishlist">wishlist</a>. Tell staff before you buy so two people don’t get the same saw.</p>','content/support/wishlist.md','other','2026.1',1788548400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-sponsors',NULL,NULL,'business-sponsors','Business sponsorships','<p><strong>Bench Sponsor — $500/yr</strong> Name plate on a workbench.</p><p><strong>Machine Sponsor — $1,500–2,500/yr</strong> Logo on the laser or plasma table; mention in every class that uses it.</p><p><strong>Founding Sponsor — $5,000/yr</strong> All of the above plus a hosted team event.</p><p>Every sponsorship also funds scholarship seats.</p>','content/support/business-sponsors.md','other','2026.1',1788548400000,1,1748797200000,1788548400000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-learn-resin-safety',NULL,NULL,'learn/resin/safety','Resin safety and PPE',replace('<h1>Resin safety and PPE</h1>\n<p>This lesson is written for The Box. There is no outside video good enough to gate this certification on. Read it carefully — the quiz safety questions come from here.</p>\n<h2>Why resin is different from FDM</h2>\n<p>Uncured photopolymer resin is a <strong>skin sensitizer</strong>. Repeated unprotected contact can produce a permanent allergy. Once that allergy exists, you may never be able to work with resin again. The hazard is chronic, not dramatic: nothing hurts the first time, and that is exactly how people get hurt.</p>\n<p>IPA (isopropyl alcohol) used for washing is <strong>flammable</strong> and its vapour is an inhalation hazard. Treat both materials as chemical PPE jobs, not craft-station habits.</p>\n<h2>Required PPE — every session</h2>\n<ul>\n<li><strong>Nitrile gloves only</strong> — never latex. Latex is permeable to resin chemistry.</li>\n<li><strong>Eye protection</strong> — splash risk when pouring, scraping, or washing.</li>\n<li><strong>Long sleeves / apron</strong> as needed so bare skin is not over the vat.</li>\n<li><strong>Ventilation running</strong> before you open resin or IPA.</li>\n</ul>\n<p>If any of those is missing, do not start.</p>\n<h2>Skin contact</h2>\n<p>If uncured resin gets on bare skin:</p>\n<ol>\n<li>Wash immediately with <strong>soap and water</strong>.</li>\n<li>Do <strong>not</strong> wipe with IPA on skin — alcohol drives resin further in and strips the skin barrier.</li>\n<li>Tell staff if exposure was more than a brief splash.</li>\n</ol>\n<h2>Waste rules</h2>\n<ul>\n<li>Cure <strong>every</strong> failed print, support, drip, and paper towel that touched liquid resin under UV before it goes in the trash.</li>\n<li>Liquid resin waste goes in the <strong>labeled resin waste container</strong> — not the sink, not the general trash.</li>\n<li>Used IPA that is too dirty to wash with goes in the <strong>labeled used-IPA container</strong>. Staff take it to King County Moderate Risk Waste. <strong>Never pour IPA down the drain.</strong></li>\n</ul>\n<h2>First session</h2>\n<p>Nobody runs resin unsupervised on their first session. Book a checkoff. The certification is the safety system for a machine members often leave running — treat the lesson accordingly.</p>\n<h2>Before you walk away from a running print</h2>\n<p>Resin prints <strong>may</strong> run unattended (unlike the laser and plasma table). Before you leave:</p>\n<ul>\n<li>Gloves off and disposed or bagged correctly</li>\n<li>Lid closed</li>\n<li>Ventilation left running</li>\n<li>Your name and expected finish time on the machine</li>\n</ul>\n','\n',char(10)),'content/lessons/resin/safety.md','lesson','2026.1',1788807600000,1,1788807600000,1788807600000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-learn-resin-printing',NULL,NULL,'learn/resin/printing','Printing on the Saturn',replace('<h1>Printing on the Saturn</h1>\n<p>The Box runs an <strong>Elegoo Saturn 2 (8K)</strong> with Chitubox. Watch the assigned videos for the full workflow; this page is the shop framing.</p>\n<h2>Shop rules that do not appear in YouTube</h2>\n<ul>\n<li>Use the shop Chitubox profile for the resin we stock — do not invent exposure settings from a home printer.</li>\n<li>Check the FEP film before every job. Cloudy, scratched, or sagging film → stop and get staff.</li>\n<li>A failed print stuck to the vat film: <strong>stop and get staff</strong>. Digging at the FEP with a tool can puncture it and dump resin into the optics.</li>\n<li>Levelling and home-position checks are part of every session, not optional “once when new.”</li>\n</ul>\n<h2>Unattended prints</h2>\n<p>Printers may run unattended. Heat/blade machines may not. Before walking away: lid closed, ventilation on, name and finish time on the machine.</p>\n','\n',char(10)),'content/lessons/resin/printing.md','lesson','2026.1',1788807600000,1,1788807600000,1788807600000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-learn-resin-wash-cure',NULL,NULL,'learn/resin/wash-cure','Washing and curing',replace('<h1>Washing and curing</h1>\n<p>Wash <strong>then</strong> cure. Curing a sticky, uncured surface locks contamination onto the part and leaves a contact hazard for the next person.</p>\n<h2>Shop practice</h2>\n<ul>\n<li>Use the wash/cure station as posted at the machine (model may differ from the Mercury XS in the video — the workflow is the same).</li>\n<li>Change IPA only per staff schedule; do not dump dirty wash liquid yourself except into the labeled used-IPA container.</li>\n<li>Nothing leaves the resin area uncured — including failed prints and supports.</li>\n<li>Cap IPA between uses. Keep it away from ignition sources (plasma table lives in the same building).</li>\n</ul>\n','\n',char(10)),'content/lessons/resin/wash-cure.md','lesson','2026.1',1788807600000,1,1788807600000,1788807600000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-learn-embroidery-basics',NULL,NULL,'learn/embroidery/basics','Embroidery machine basics',replace('<h1>Embroidery machine basics</h1>\n<p>Best-practice path for The Box&#39;s embroidery station (Brother-class single-needle; confirm the exact model at the machine). Hands-on checkoff is still required.</p>\n<h2>Core habits</h2>\n<ul>\n<li>Needle up, presser foot rules, and bobbin orientation follow the machine&#39;s numbered path — same discipline as sewing.</li>\n<li><strong>Never</strong> pull fabric while the machine is stitching; the hoop and feed must control movement.</li>\n<li>Keep fingers clear of the needle and the moving hoop arm.</li>\n<li>Stop immediately on a bird&#39;s nest, broken needle, or unusual noise — find every needle fragment before restarting.</li>\n</ul>\n<h2>Files</h2>\n<p>Bring designs in the shop&#39;s accepted formats (typically PES / DST — confirm at the station). USB workflow is covered in the PE800 beginner video.</p>\n','\n',char(10)),'content/lessons/embroidery/basics.md','lesson','2026.1',1788807600000,1,1788807600000,1788807600000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-learn-embroidery-hooping',NULL,NULL,'learn/embroidery/hooping','Hooping and stabilizer',replace('<h1>Hooping and stabilizer</h1>\n<p>Most embroidery failures are hooping or stabilizer failures, not machine failures.</p>\n<h2>Stabilizer cheat sheet</h2>\n<ul>\n<li><strong>Cutaway</strong> — knits, t-shirts, anything that stretches. It stays behind the design for the life of the garment.</li>\n<li><strong>Tearaway</strong> — stable wovens (canvas, denim, many towels) where you want the backing gone after stitching.</li>\n<li><strong>Water-soluble topper</strong> — towels, fleece, and pile fabrics so stitches sit on top instead of sinking in.</li>\n</ul>\n<h2>Hooping</h2>\n<p>Layer outer hoop → stabilizer → fabric → inner hoop. Fabric should be taut like a drum <strong>without</strong> stretching the grain. Excess fabric tucked so it cannot catch the embroidery arm.</p>\n<p>If the design puckers after unhooping, you probably stretched the fabric in the hoop — re-hoop; do not pull harder mid-stitch.</p>\n','\n',char(10)),'content/lessons/embroidery/hooping.md','lesson','2026.1',1788807600000,1,1788807600000,1788807600000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-learn-sublimation-overview',NULL,NULL,'learn/sublimation/overview','Sublimation overview',replace('<h1>Sublimation overview</h1>\n<p>Sublimation turns printed dye into a gas under heat and bonds it into polyester (or polymer-coated blanks). Best-practice settings; confirm The Box&#39;s posted temperatures at the press.</p>\n<h2>Hard rules</h2>\n<ul>\n<li>Designs must be <strong>mirrored</strong> before printing (unless the software already mirrors for the product).</li>\n<li>Fabric garments need high polyester content — ideally <strong>100% polyester</strong> — and light colours. Cotton will not hold dye the same way.</li>\n<li>Heat press plates get hot enough to burn. Use heat-resistant tape, protect the press with butcher paper, and never leave a closed press unattended while it is cycling.</li>\n<li>Secure the transfer so it cannot shift — ghosting (double image) is almost always movement during open/close.</li>\n</ul>\n','\n',char(10)),'content/lessons/sublimation/overview.md','lesson','2026.1',1788807600000,1,1788807600000,1788807600000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-learn-sublimation-software',NULL,NULL,'learn/sublimation/software','Sawgrass Print Manager',replace('<h1>Sawgrass Print Manager</h1>\n<p>The shop computer prints through <strong>Sawgrass Print Manager / Print Utility</strong>. Use the substrate preset that matches what you are pressing. Mirroring, colour profile, and quality live in that utility — not in a random “print to USB” path.</p>\n<p>Watch the assigned video for the click-path. If colour looks wrong, check: preset, paper print-side, and that you mirrored — before blaming the printer.</p>\n','\n',char(10)),'content/lessons/sublimation/software.md','lesson','2026.1',1788807600000,1,1788807600000,1788807600000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-learn-sublimation-heat-press',NULL,NULL,'learn/sublimation/heat-press','Heat press',replace('<h1>Heat press</h1>\n<p>Typical garment starting point (edit when The Box posts its chart): about <strong>380–400°F</strong>, firm pressure, ~45–60 seconds on 100% polyester — then peel carefully while hot surfaces stay hot.</p>\n<h2>Every press</h2>\n<ol>\n<li>Lint-roll and pre-press briefly to remove moisture/wrinkles.</li>\n<li>Butcher paper (or press pillow + paper) so ink cannot contaminate the platen or the back of the shirt.</li>\n<li>Tape the transfer; do not rely on gravity.</li>\n<li>Stay with the press for the full cycle.</li>\n<li>Cool on a clean surface; do not fold a hot transfer against itself.</li>\n</ol>\n','\n',char(10)),'content/lessons/sublimation/heat-press.md','lesson','2026.1',1788807600000,1,1788807600000,1788807600000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-learn-shop-orientation-basics',NULL,NULL,'learn/shop-orientation/basics','How we work in this shop',replace('<h1>How we work in this shop</h1>\n<p>Shop layout, hours, sign-in, cleanup, and the rule: if you did not turn it on, do not turn it off. Staff will cover abandoned-property timing and a walkthrough of the floor.</p>\n<h2>Dust and your lungs</h2>\n<ul>\n<li>The hazard is <strong>fine airborne wood dust</strong>, not just the chips you can see on the floor.</li>\n<li>Use dust collection and respirators as posted for the machine and material.</li>\n<li>Fine dust can hang in the air after the shop looks clear — keep filtration/respirators in mind after cutting stops.</li>\n<li>Ask staff who empties collectors and where respirators live.</li>\n</ul>\n<p>Watch the Alpine basics video (required). The optional dust video goes deeper if you want more context.</p>\n','\n',char(10)),'content/lessons/shop-orientation/basics.md','lesson','2026.1',1788807600000,1,1788807600000,1788807600000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-history',NULL,NULL,'history','How The Box got here',replace('<p>The Box started because Burien needed a public shop. Debra George, Discover Burien’s executive director, watched a Farmers Market vendor struggle to make enough of their hand-crafted boxes to sell. The city had makers. It did not have a room with the tools.</p>\n<p>In 2021, Discover Burien cleared a former classroom on the lower level of 611 SW 152nd Street, bought equipment, and hired staff — the Highline area’s first publicly accessible makerspace. Soft opening was October 2021. A grand opening followed on March 16, 2022.</p>\n<p>Denise Ferguson, a long-time Discover Burien employee and Burien small-business owner, laid out the floor: work areas by craft, machines grouped so you can learn one station and then the next. Mitchell Allen, The Box’s makerspace manager, came from museums and after-school programs. His job, as he put it, is to be the catalyst — get people to his level on a machine, then let the community outrun him.</p>\n<p>The original brief was a launchpad for micro-businesses: small production runs, prototypes, branded merch. It is also a place to make for its own sake — costumes, cribbage boards, a first 3D print. Membership, certifications, and classes live in this portal now. The rest of Discover Burien’s public story stays on discoverburien.org.</p>','\n',char(10)),'content/about/history.md','other','2026.1',1789930800000,1,1789930800000,1789930800000,NULL);
INSERT OR IGNORE INTO ContentPage VALUES('content-staff',NULL,NULL,'staff','Staff & instructors',replace('<p>The Box is a program of Discover Burien. These are the people who keep the shop open, and the instructors who teach classes on the calendar.</p>\n<p>Want to teach? Pitch a class — sewing, laser, 3D printing, embroidery, jewelry, CNC, and more are welcome. Proposals go to staff; classes run through Discover Burien.</p>','\n',char(10)),'content/about/staff.md','other','2026.1',1789930800000,1,1789930800000,1789930800000,NULL);
